INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Gilt das Open Closed Principle nur für Objektorientierung?', 2, '[{"text": "Nein", "correct": true, "because": "Auch in anderen Paradigmen anwendbar"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit dem Open Closed Principle?', 3, '[{"text": "Erweiterbarkeit ohne Änderung", "correct": true, "because": "Code bleibt stabil"}, {"text": "Code kürzen", "correct": false, "because": "Nicht primär"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Kein Performance-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken unterstützen das Open Closed Principle?', 5, '[{"text": "Interfaces", "correct": true, "because": "Erweiterung definieren"}, {"text": "Abstrakte Klassen", "correct": true, "because": "Basis für Erweiterung"}, {"text": "Globale Variablen", "correct": false, "because": "Erhöht Kopplung"}, {"text": "Direkte Änderungen", "correct": false, "because": "Widerspricht OCP"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) OCP nutzt Polymorphismus. b) Es vermeidet jede Code-Änderung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Änderungen teilweise nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Open Closed Principle?', 4, '[{"text": "Erweiterbarkeit", "correct": false, "because": "Kern des Prinzips"}, {"text": "Abstraktion", "correct": false, "because": "Unterstützt OCP"}, {"text": "Farbschema", "correct": true, "because": "Kein Code-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob OCP mehr Planung braucht?', 2, '[{"text": "Ja", "correct": true, "because": "Abstraktion erfordert Design"}, {"text": "Nein", "correct": false, "because": "Planung essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel folgt dem Open Closed Principle?', 3, '[{"text": "Neue Klasse über Interface", "correct": true, "because": "Erweitert ohne Änderung"}, {"text": "If-Else für neue Fälle", "correct": false, "because": "Ändert bestehenden Code"}, {"text": "Globale Funktion", "correct": false, "because": "Keine Abstraktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das Open Closed Principle?', 5, '[{"text": "Stabilität", "correct": true, "because": "Bestehender Code bleibt"}, {"text": "Flexibilität", "correct": true, "because": "Neue Features einfach"}, {"text": "Weniger Zeilen", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) OCP fördert Wiederverwendung. b) Es macht Tests überflüssig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tests bleiben nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für das Open Closed Principle?', 4, '[{"text": "Polymorphismus", "correct": false, "because": "Unterstützt Erweiterung"}, {"text": "Abstraktion", "correct": false, "because": "Grundlage OCP"}, {"text": "UI-Animationen", "correct": true, "because": "Kein Code-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist OCP ohne Interfaces möglich?', 2, '[{"text": "Ja", "correct": true, "because": "Andere Abstraktionen möglich"}, {"text": "Nein", "correct": false, "because": "Interfaces üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften fördert das Open Closed Principle?', 4, '[{"text": "Erweiterbarkeit", "correct": true, "because": "Neue Features ohne Änderung"}, {"text": "Wartbarkeit", "correct": true, "because": "Stabiler Code"}, {"text": "Schnellere Builds", "correct": false, "because": "Kein Build-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass OCP nur für große Projekte ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine profitieren"}, {"text": "Ja", "correct": false, "because": "Universell nützlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Open Closed Principle?', 3, '[{"text": "Abstrakte Schnittstellen", "correct": true, "because": "Ermöglicht Erweiterung"}, {"text": "Schnelle Änderungen", "correct": false, "because": "Widerspricht OCP"}, {"text": "Maximale Funktionen", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) OCP reduziert Kopplung. b) Es garantiert Fehlerfreiheit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fehlerfreiheit nicht Ziel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat das Open Closed Principle?', 5, '[{"text": "Höherer Designaufwand", "correct": true, "because": "Abstraktion braucht Zeit"}, {"text": "Mehr Klassen", "correct": true, "because": "Erweiterung trennt"}, {"text": "Langsamere Ausführung", "correct": false, "because": "Kein Performance-Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Open Closed Principle unwichtig?', 3, '[{"text": "Abstraktion", "correct": false, "because": "Grundlage OCP"}, {"text": "Erweiterbarkeit", "correct": false, "because": "Kernziel"}, {"text": "UI-Layout", "correct": true, "because": "Kein Code-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erhöht OCP die Komplexität?', 3, '[{"text": "Ja", "correct": true, "because": "Abstraktion kann komplexer sein"}, {"text": "Nein", "correct": false, "because": "Langfristig einfacher"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob OCP Refactoring erleichtert?', 2, '[{"text": "Ja", "correct": true, "because": "Stabiler Code änderbar"}, {"text": "Nein", "correct": false, "because": "Erweiterung vereinfacht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug unterstützt das Open Closed Principle?', 4, '[{"text": "Dependency Injection", "correct": true, "because": "Fördert Erweiterbarkeit"}, {"text": "Compiler-Optimierung", "correct": false, "because": "Anderer Fokus"}, {"text": "UI-Framework", "correct": false, "because": "Design-spezifisch"}]');
